async def main():
  srv=subprocess.Popen([sys.executable,'-m','http.server','8799'],cwd=ROOT,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL);time.sleep(1)
  bad=0;fails=[]
  # cases run a few at a time (SMOKE_JOBS, default 3); a failure is retried once alone, so a slow machine can't fake a failure
  jobs=int(os.environ.get('SMOKE_JOBS','2'))
  try:
    async with async_playwright() as p:
      chrome='/usr/bin/google-chrome' if os.path.exists('/usr/bin/google-chrome') else None
      b=await p.chromium.launch(executable_path=chrome,args=['--use-gl=swiftshader','--enable-webgl','--ignore-gpu-blocklist'])
      only={int(float(a)) for a in sys.argv[1:] if a.lstrip('-').replace('.','').isdigit()}
      sem=asyncio.Semaphore(jobs)
      async def run(y,cmd):
        async with sem:
          pg=await b.new_page(viewport={'width':393,'height':760});errs=[]
          pg.on('pageerror',lambda e: errs.append(str(e)))
          try:
            await pg.goto(f'http://localhost:8799/test.html#{y}')
            # wait for the world to finish booting (up to 45 s) instead of a fixed pause, then let data files settle
            for _ in range(90):
              if await pg.evaluate("()=>!!window.HS&&getComputedStyle(document.getElementById('load')).display==='none'"):break
              await pg.wait_for_timeout(500)
            await pg.wait_for_timeout(9000)
            if cmd:
              try: await pg.evaluate("c=>HS.X(c)",cmd)
              except Exception as e: errs.append('CMD '+str(e)[:200])
            await pg.wait_for_timeout(6000)
            ok=await pg.evaluate("typeof simY!=='undefined'||!!document.getElementById('year').textContent")
          except Exception as e: errs.append('RUN '+str(e)[:200]);ok=False
          finally: await pg.close()
          return (not errs and ok),errs
      sel=[(y,c) for y,c in CASES if not only or y in only]
      res=await asyncio.gather(*[run(y,c) for y,c in sel])
      for (y,cmd),(ok,errs) in zip(sel,res):
        if not ok and jobs>1:
          sem2=jobs;jobs_save=sem;sem=asyncio.Semaphore(1);ok,errs2=await run(y,cmd);sem=jobs_save
          if ok: errs=['passed on retry alone']
          else: errs=errs2
        print('PASS' if ok else 'FAIL',y,cmd[:50],errs[:3],flush=True);bad+=(not ok)
      await b.close()
  finally: srv.terminate()
  sys.exit(1 if bad else 0)
asyncio.run(main())
